java.awt.image.BufferedImage testImg = new java.awt.image.BufferedImage(10, 10, java.awt.image.BufferedImage.TYPE_INT_RGB);
for (int y = 0; y < 5; y++) {
    for (int x = 0; x < 5; x++) {
        testImg.setRGB(x, y, 0xFF123456);
    }
}

java.util.List<net.coobird.thumbnailator.filters.ImageFilter> filters = new java.util.ArrayList<>();
filters.add(net.coobird.thumbnailator.filters.Flip.HORIZONTAL);
filters.add(net.coobird.thumbnailator.filters.Flip.VERTICAL);

java.awt.image.BufferedImage result = net.coobird.thumbnailator.Thumbnails.of(testImg)
    .scale(1.0)
    .addFilters(filters)
    .asBufferedImage();

int rgb = result.getRGB(8, 8) & 0xFFFFFF;
assert rgb == 0x123456 : "Block not flipped correctly, got " + Integer.toHexString(rgb);

int rgbEmpty = result.getRGB(2, 2) & 0xFFFFFF;
assert rgbEmpty == 0x000000 : "Empty area not flipped correctly, got " + Integer.toHexString(rgbEmpty);

System.out.println("__CHECK__ addFilters " + Integer.toHexString(rgb));

